package com.lianxibu.site.config;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.lianxibu.site.service.jobs.*;import com.lianxibu.site.repository.jobs.JdbcCollectorNodeFacts;import com.lianxibu.site.domain.jobs.CollectorNodeFacts;
import java.nio.file.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import org.springframework.boot.test.context.runner.ApplicationContextRunner;
class CollectorNodeMonitoringConfigurationTest {
 @TempDir Path directory;
 String[] flags(){return new String[]{"site.ops.collector-monitoring.enabled=true","site.browser.enabled=true","site.collector.enabled=true"};}
 String scopes(){return "{\"schema_version\":\"collector-node-monitor-bindings-v1\",\"node_ids\":[\"fictional-node-a\",\"fictional-node-b\"]}";}
 ApplicationContextRunner runner(Path file){var executor=mock(ScheduledExecutorService.class);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenReturn(mock(ScheduledFuture.class));return new ApplicationContextRunner().withUserConfiguration(CollectorNodeMonitoringConfiguration.class).withBean(javax.sql.DataSource.class,()->mock(javax.sql.DataSource.class)).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->mock(org.springframework.transaction.PlatformTransactionManager.class)).withBean("collectorNodeMonitoringExecutor",ScheduledExecutorService.class,()->executor).withPropertyValues(flags()).withPropertyValues("SITE_COLLECTOR_MONITOR_NODES="+file);}
 @Test void eachMissingFlagCreatesNoNativeProviderOrThread(){for(int disabled=0;disabled<3;disabled++){var values=flags();values[disabled]=values[disabled].replace("true","false");new ApplicationContextRunner().withUserConfiguration(CollectorNodeMonitoringConfiguration.class).withPropertyValues(values).run(c->{assertNull(c.getStartupFailure());assertTrue(c.getBeansOfType(CollectorNodeMonitoringConfiguration.Batch.class).isEmpty());assertTrue(c.getBeansOfType(ScheduledExecutorService.class).isEmpty());});}}
 @Test void actualFactoryBuildsEveryNativeSourceCycleWithZeroStartupSql()throws Exception{Path file=directory.resolve("scopes.json");Files.writeString(file,scopes());runner(file).withBean(CollectorNodeFacts.Api.class,()->id->{fail("fake external facts cannot enter factory");return null;}).run(c->{assertNull(c.getStartupFailure());var batch=c.getBean(CollectorNodeMonitoringConfiguration.Batch.class);assertEquals(2,batch.cycles().size());assertInstanceOf(JdbcCollectorNodeFacts.class,batch.nativeFacts());assertTrue(c.getBean(CollectorNodeMonitoringConfiguration.Loop.class).isRunning());assertEquals("CollectorNodeMonitoringBatch[redacted]",batch.toString());verifyNoInteractions(c.getBean(javax.sql.DataSource.class),c.getBean(org.springframework.transaction.PlatformTransactionManager.class));});}
 @Test void malformedMissingDuplicateOverflowAndAbsentNativeDependenciesFailClosed()throws Exception{
  Path file=directory.resolve("nodes.json");for(String text:List.of("{\"schema_version\":\"collector-node-monitor-bindings-v1\",\"node_ids\":[]}",scopes().replace("fictional-node-b","fictional-node-a"),scopes().replace("bindings-v1","bindings-v2"),scopes().replace("\"node_ids\"","\"unknown\""),scopes().replace("fictional-node-a","x".repeat(65))," ".repeat(65537),"{\"schema_version\":\"collector-node-monitor-bindings-v1\",\"node_ids\":["+String.join(",",java.util.stream.IntStream.range(0,129).mapToObj(i->"\"fictional-"+i+"\"").toList())+"]}")){Files.writeString(file,text);runner(file).run(c->assertNotNull(c.getStartupFailure()));}Files.writeString(file,scopes());new ApplicationContextRunner().withUserConfiguration(CollectorNodeMonitoringConfiguration.class).withPropertyValues(flags()).withPropertyValues("SITE_COLLECTOR_MONITOR_NODES="+file).run(c->assertNotNull(c.getStartupFailure()));assertThrows(IllegalStateException.class,()->CollectorNodeMonitoringConfiguration.load("nodes.json"));assertThrows(IllegalStateException.class,()->CollectorNodeMonitoringConfiguration.load(directory.resolve("absent.json").toString()));
 }
 @Test void cycleFailureDoesNotStarveOtherSourceAndNextMinuteCanRetry(){var first=mock(CollectorNodeMonitoringCycle.class);var second=mock(CollectorNodeMonitoringCycle.class);when(first.tick()).thenThrow(new IllegalStateException("fictional unavailable")).thenReturn(CollectorNodeMonitoringCycle.Outcome.SAMPLED);var batch=new CollectorNodeMonitoringConfiguration.Batch(List.of(first,second),mock(CollectorNodeFacts.Api.class));var executor=mock(ScheduledExecutorService.class);var tick=new AtomicReference<Runnable>();var future=mock(ScheduledFuture.class);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));assertEquals(TimeUnit.SECONDS.toNanos(50),(long)a.getArgument(1));assertEquals(TimeUnit.SECONDS.toNanos(60),(long)a.getArgument(2));return future;});var loop=new CollectorNodeMonitoringConfiguration.Loop(batch,executor,Clock.fixed(Instant.parse("2026-01-01T00:00:10Z"),ZoneOffset.UTC));loop.start();verify(first).start();verify(second).start();tick.get().run();assertTrue(loop.hasFailure());verify(second).tick();tick.get().run();assertFalse(loop.hasFailure());verify(first,times(2)).tick();verify(second,times(2)).tick();loop.stop();tick.get().run();verify(first,times(2)).tick();verify(first).stop();verify(second).stop();verify(future).cancel(true);assertFalse(loop.isRunning());}
 @Test void shutdownCallbackWaitsAndRejectedScheduleNeverPretendsRunning()throws Exception{var cycle=mock(CollectorNodeMonitoringCycle.class);var batch=new CollectorNodeMonitoringConfiguration.Batch(List.of(cycle),mock(CollectorNodeFacts.Api.class));var executor=mock(ScheduledExecutorService.class);var tick=new AtomicReference<Runnable>();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var done=new CountDownLatch(1);when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenAnswer(a->{tick.set(a.getArgument(0));return mock(ScheduledFuture.class);});when(cycle.tick()).thenAnswer(a->{entered.countDown();assertTrue(release.await(2,TimeUnit.SECONDS));return CollectorNodeMonitoringCycle.Outcome.STOPPED;});var loop=new CollectorNodeMonitoringConfiguration.Loop(batch,executor,Clock.systemUTC());var pool=Executors.newSingleThreadExecutor();try{loop.start();pool.submit(()->tick.get().run());assertTrue(entered.await(1,TimeUnit.SECONDS));loop.stop(done::countDown);assertEquals(1,done.getCount());assertThrows(IllegalStateException.class,loop::start);release.countDown();assertTrue(done.await(1,TimeUnit.SECONDS));}finally{release.countDown();pool.shutdownNow();}when(executor.scheduleAtFixedRate(any(Runnable.class),anyLong(),anyLong(),eq(TimeUnit.NANOSECONDS))).thenThrow(new RejectedExecutionException());assertThrows(RejectedExecutionException.class,loop::start);assertFalse(loop.isRunning());}
}
